(() => {
'use strict';
const $ = s => document.querySelector(s), tools = window.WAREZ_TOOLS, config=window.WAREZ_CONFIG;
const read = (key,fallback) => {try{return JSON.parse(localStorage.getItem(key))||fallback}catch{return fallback}};
const write=(key,value)=>{try{localStorage.setItem(key,JSON.stringify(value))}catch{}};
let lang=read('warez-language','en'), saved=new Set(read('warez-saved',[]).filter(id=>tools.some(t=>t.id===id))), compare=new Set(), category='All tools', expanded=false, savedOnly=false;
const categories=[['All tools','✳','כל הכלים'],['Productivity','▧','פרודוקטיביות'],['Design','◈','עיצוב'],['Marketing','↗','שיווק'],['Automation','⚯','אוטומציה'],['Operations','◷','תפעול'],['Sales','◇','מכירות']];
const he={navGear:'ציוד לעבודה',gearLabel:'מעבר לתוכנה',gearTitle:'שדרוג קטן ליום העבודה.',gearGuide:'למדריך הקנייה באנגלית ↗',gearIntro:'תוכנה שימושית צריכה סביבת עבודה נוחה. שלוש הצעות לחיבור השולחן, לעבודה יומיומית ולאחסון קבצים. פירוט המוצרים באנגלית.',gearAmazon:'למוצר באמזון ↗',gearFoot:'הצעות מערכת, ללא בדיקה מעשית. הקישורים מובילים ל-Amazon.com בארה״ב. בדקו מוכר, משלוח לישראל, עלויות יבוא, החזרות ואחריות. מחירים וזמינות מעודכנים מופיעים באמזון.',navDiscover:'כלים',navStacks:'ערכות התחלה',navNotes:'מדריכים',saved:'הרשימה שלי',partner:'ליוצרים ↗',eyebrow:'רשימת התוכנות העצמאית שלכם',hero:'תוכנה טובה.<br><em>עסק טוב יותר.</em>',intro:'פחות חיפוש בין לשוניות. יותר עשייה.<br>מוצאים את הכלים הנכונים לצעד הבא של העסק.',search:'מוצאים כלים ↗',try:'נסו:',trust1:'בחירה עצמאית',trust2:'קישורים רשמיים',trust3:'יתרונות ומגבלות, בלי הגזמות',trust4:'בשביל צוותים קטנים',directoryLabel:'ארגז הכלים',directoryTitle:'מוצאים את מה שעובד בשבילכם.',directoryIntro:'אוסף ממוקד. בחירה ברורה.<br>מתחילים ממה שצריך לעשות.',freeOnly:'אפשרות חינמית',reset:'איפוס',pricingNote:'מסלולים חינמיים עשויים לכלול מגבלות. בדקו תמיד את התנאים המעודכנים באתר הספק.',showAll:'לכל 24 הכלים ↓',stackLabel:'לא מתחילים מדף ריק',stackTitle:'ערכות קטנות. התחלות גדולות.',stackIntro:'כלים שמתאימים יחד.<br>בוחרים נקודת התחלה ומתאימים אותה לצרכים שלכם.',soloTitle:'אדם אחד.<br>הרבה כובעים.',soloText:'רעיונות, טפסי לקוחות ופגישות — בלי עומס ניהולי מיותר.',creativeTitle:'מהרעיון הראשון<br>עד לגרסה הסופית.',creativeText:'מקום משותף לעיצוב, ארגון העבודה והסבר הפרטים.',growthTitle:'עבודה טובה<br>צריכה קהל.',growthText:'מחברים טפסים, אימייל ותהליכים — ומשקיעים יותר במסר.',viewStack:'פותחים את הערכה ↗',notesLabel:'מדריכים מהשטח',notesTitle:'בוחרים טוב. עובדים טוב יותר.',editorial:'הבחירות של WAREZ',guideFree:'העלות הנסתרת של מסלול חינמי',guideIsrael:'צ׳קליסט תוכנה לצוותים בישראל',guideAuto:'מתחילים באוטומציה של המשימה המשעממת',readGuide:'לקריאת המדריך באנגלית ↗',partnerLabel:'בונים משהו שימושי?',partnerTitle:'הכירו את הלקוח הבא<br>של העסק שלכם.',partnerText:'Warez נפתח למספר מוגבל של חסויות המסומנות בבירור. בחירת הכלים נשארת עצמאית.',sponsor:'לקבלת מסמך שותפות ↗',partnerNote:'אתר בשלבי השקה. אין הבטחות לקהל או לביצועים.',futureSponsor:'מיקום עתידי לחסות',sponsorShape:'דברים שימושיים<br>ראויים לחשיפה.',sponsorFoot:'מסומן בבירור. ממוקם במחשבה.',footerLine:'פחות עומס של תוכנות.<br>יותר אפשרויות.',about:'אודות ושיטת הבחירה',disclosure:'גילוי מסחרי',privacy:'פרטיות',independent:'גילוי תוכנות עצמאי. שמות המוצרים שייכים לבעליהם.',backTop:'למעלה ↑',compare:'השוואה ↗'};
const english={};document.querySelectorAll('[data-t]').forEach(el=>english[el.dataset.t]=el.innerHTML);
const tr=(en,hebrew)=>lang==='he'?hebrew:en;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const catName=c=>lang==='he'?(categories.find(x=>x[0]===c)||[])[2]||c:c;
const validUrl=u=>{try{return new URL(u).protocol==='https:'}catch{return false}};
const outbound=t=>validUrl(config.affiliateLinks[t.id])?config.affiliateLinks[t.id]:t.url;
const affiliate=t=>validUrl(config.affiliateLinks[t.id]);
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').hidden=true,2800)}
function modal(html){$('#dialog-content').innerHTML=html;if(!$('#dialog').open)$('#dialog').showModal()}
function logo(t){return `<span class="tool-logo" style="background:${t.color};color:${t.ink}">${esc(t.icon)}</span>`}
function renderCategories(){ $('#categories').innerHTML=categories.map(([name,icon])=>`<button class="${category===name?'active':''}" aria-pressed="${category===name}" data-category="${name}"><span class="cat-icon" aria-hidden="true">${icon}</span>${catName(name)}</button>`).join('') }
function render(){renderCategories();const q=$('#search').value.toLowerCase().trim();let list=tools.filter(t=>(category==='All tools'||t.category===category)&&(!$('#free-only').checked||t.free)&&(!savedOnly||saved.has(t.id))&&(!q||`${t.name} ${t.category} ${t.desc} ${t.he} ${t.tag} ${t.best} ${t.free?'free':''}`.toLowerCase().includes(q)));if($('#sort').value==='name')list.sort((a,b)=>a.name.localeCompare(b.name));const shown=expanded?list:list.slice(0,6);$('#result-count').textContent=tr(`${list.length} tools${savedOnly?' in your shortlist':''} · ${shown.length} shown`,`${list.length} כלים${savedOnly?' ברשימה שלכם':''} · מוצגים ${shown.length}`);$('#tool-grid').innerHTML=shown.length?shown.map(t=>`<article class="tool-card"><div class="card-top">${logo(t)}<div><h3>${t.name}</h3><div class="tool-category">${catName(t.category)}</div></div><button class="save-button ${saved.has(t.id)?'on':''}" data-save="${t.id}" aria-label="${saved.has(t.id)?'Remove':'Save'} ${t.name}" aria-pressed="${saved.has(t.id)}">${saved.has(t.id)?'▣':'▢'}</button></div><p>${lang==='he'?t.he:t.desc}</p><div class="card-labels"><span class="pill">${t.free?tr('Free option', 'אפשרות חינמית'):tr('Paid / self-hosted','בתשלום / באירוח עצמי')}</span><span class="pill neutral">${t.tag}</span></div><div class="card-bottom"><button data-detail="${t.id}">${tr('Take a closer look ↗','לפרטים נוספים ↗')}</button><label class="compare-label"><input type="checkbox" data-compare="${t.id}" ${compare.has(t.id)?'checked':''}>${tr('Compare','השוואה')}</label></div></article>`).join(''):`<div class="empty"><h3>${tr('A little too specific?','לא נמצאו כלים מתאימים')}</h3><p>${tr('Try a broader search or reset the filters.','נסו חיפוש אחר או אפסו את המסננים.')}</p><button class="outline" data-reset>${tr('Reset filters','איפוס מסננים')}</button></div>`;$('#show-all').hidden=expanded||list.length<=6;$('#show-all').textContent=tr(`Explore all ${list.length} tools ↓`,`לכל ${list.length} הכלים ↓`);$('#saved').textContent=tr(`My shortlist${saved.size?' ('+saved.size+')':''}`,`הרשימה שלי${saved.size?' ('+saved.size+')':''}`);$('#saved').classList.toggle('dark',savedOnly);$('#compare-tray').hidden=!compare.size;$('#compare-count').textContent=tr(`${compare.size} of 3 tools selected`,`${compare.size} מתוך 3 כלים נבחרו`);$('#compare-open').disabled=compare.size<2;}
function reset(){category='All tools';$('#search').value='';$('#free-only').checked=false;$('#sort').value='editorial';savedOnly=false;expanded=false;render()}
function setLanguage(){document.documentElement.lang=lang;document.documentElement.dir=lang==='he'?'rtl':'ltr';document.querySelectorAll('[data-t]').forEach(el=>el.innerHTML=lang==='he'?(he[el.dataset.t]||english[el.dataset.t]):english[el.dataset.t]);$('#search').placeholder=tr('What do you want to get done?','מה תרצו לעשות?');$('#search').setAttribute('aria-label',tr('Search tools','חיפוש כלים'));$('#language').setAttribute('aria-label',tr('Switch to Hebrew','Switch to English'));$('#sort').options[0].text=tr('Editorial order','סדר עריכה');$('#sort').options[1].text=tr('Name A–Z','לפי שם');render()}
function toolDetail(id){const t=tools.find(t=>t.id===id);if(!t)return;modal(`<div class="detail-top">${logo(t)}<div><div class="eyebrow">${catName(t.category)}</div><h2>${t.name}</h2></div></div><p class="modal-intro">${lang==='he'?t.he:t.desc}</p><span class="pill">${esc(t.model)}</span><h3>${tr('A good fit for','מתאים במיוחד ל')}</h3><p lang="en" dir="ltr">${t.best}</p><h3>${tr('The tradeoff to check','מה כדאי לבדוק')}</h3><p lang="en" dir="ltr">${t.watch}</p><div class="notice">${tr('For an Israeli team: test Hebrew input, RTL documents, local invoicing requirements, support hours, and your actual billing currency before committing.','לצוות בישראל: בדקו קלט בעברית, מסמכים מימין לשמאל, דרישות חשבוניות מקומיות, שעות תמיכה ומטבע חיוב לפני הבחירה.')}</div><div class="modal-actions"><a class="dark" href="${esc(outbound(t))}" target="_blank" rel="noopener noreferrer${affiliate(t)?' sponsored':''}">${tr('Visit official website ↗','לאתר הספק ↗')}</a><button class="outline" data-save="${t.id}">${saved.has(id)?tr('Remove from shortlist','הסרה מהרשימה'):tr('Save to shortlist','שמירה ברשימה')}</button></div><p class="source-note">${affiliate(t)?'Affiliate link: we may receive compensation.':'Direct vendor link. No affiliate relationship is currently configured for this tool.'}<br>Editorial summary; not a hands-on review or endorsement. <a href="${t.source}" target="_blank" rel="noopener noreferrer">Official source ↗</a> · Reviewed 16 Oct 2026. Check current vendor terms.</p>`)}
function comparison(){const items=[...compare].map(id=>tools.find(t=>t.id===id));if(items.length<2)return;const rows=[[tr('Purpose','מטרה'),t=>lang==='he'?t.he:t.desc],[tr('Category','קטגוריה'),t=>catName(t.category)],[tr('Cost model','מודל מחיר'),t=>t.model],[tr('Best fit','למי זה מתאים'),t=>t.best],[tr('Watch out for','מה לבדוק'),t=>t.watch],[tr('Official site','אתר רשמי'),t=>`<a href="${esc(outbound(t))}" rel="noopener noreferrer${affiliate(t)?' sponsored':''}" target="_blank"><u>${tr('Check current plans ↗','למסלולים העדכניים ↗')}</u></a>`]];modal(`<h2>${tr('A clearer side-by-side.','משווים ובוחרים בצורה ברורה.')}</h2><p class="modal-intro">${tr('Different jobs need different tools. Compare fit before features.','לכל משימה יש כלי מתאים. השוו התאמה לפני ספירת תכונות.')}</p><div class="compare-scroll"><table><thead><tr><th>${tr('At a glance','במבט אחד')}</th>${items.map(t=>`<th>${t.name}</th>`).join('')}</tr></thead><tbody>${rows.map(([label,fn])=>`<tr><td>${label}</td>${items.map(t=>`<td>${fn(t)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="source-note">${tr('No numerical ratings or sponsored rankings. Verify plans on the official websites.','ללא ציונים מספריים או דירוגים ממומנים. בדקו מסלולים באתרי הספקים.')}</p>`)}
const stacks={solo:{title:'The solo studio',ids:['notion','tally','cal'],text:'Keep one home for project notes. Use a form for client intake, then a booking link for the first conversation. Start with the simplest plans that meet your actual limits.'},creative:{title:'The creative team',ids:['figma','trello','loom'],text:'Design in a shared canvas, track handoffs on a board, and record short walkthroughs. Decide which tool owns each task so information does not get duplicated.'},growth:{title:'The lean growth kit',ids:['tally','mailerlite','make'],text:'Capture opt-in leads through a form, manage the audience in an email platform, then automate the handoff. Check integration availability, sending rules, and usage allowances first.'}};
function stackDetail(key){const s=stacks[key];modal(`<div class="eyebrow">STARTER STACK / EDITORIAL SUGGESTION</div><h2>${s.title}</h2><p class="modal-intro" lang="en" dir="ltr">${s.text}</p>${s.ids.map(id=>{const t=tools.find(t=>t.id===id);return `<div class="list-item">${logo(t)}<div><h3>${t.name}</h3><p>${lang==='he'?t.he:t.desc}</p></div><button data-detail="${id}">${tr('Details ↗','פרטים ↗')}</button></div>`}).join('')}<div class="modal-actions"><button class="dark" data-save-stack="${key}">${tr('Save the whole stack','שמירת כל הערכה')}</button><button class="outline" data-compare-stack="${key}">${tr('Compare these tools','השוואת הכלים')}</button></div><p class="source-note">Independent suggestions, not a claim of native integrations or tested compatibility. Confirm the workflow and current plan limits with each vendor.</p>`)}
const guides={free:{title:'The hidden cost of a free plan',body:`<p>A free tier is a useful starting point. The real decision is whether its limits fit the work you do.</p><h3>Count the thing that gets billed</h3><p>Seats, contacts, tasks, storage, and sends are different billing units. Write down the unit and your expected usage. A cheap plan can become expensive when every automation run counts.</p><h3>Check the first limit you will reach</h3><p>Look at collaboration, version history, export options, branding, and integrations. Test your most important workflow before migrating real work.</p><h3>Budget for leaving, too</h3><p>Can you export your data in a usable format? Who owns the account? How much time will migration take? Keep a short exit plan alongside your shortlist.</p><h3>A useful next step</h3><p>Choose two tools, compare their tradeoffs here, and open both official pricing pages. Record the cost at today's usage and at twice that usage.</p>`},israel:{title:'A software checklist for Israeli teams',body:`<p>A global product can work well for a local business. A few small checks can prevent a much larger migration later.</p><h3>1. Test the Hebrew workflow</h3><p>Paste mixed Hebrew and English into a real document, form, email, and PDF. Check punctuation, numbers, text direction, search, and the exported result. A Hebrew input field does not mean the entire product supports RTL.</p><h3>2. Confirm the billing context</h3><p>Check the currency charged, bank conversion fees, tax treatment, and invoice information with your provider and accountant. This directory is not tax advice and the tools are not certified here for Israeli bookkeeping requirements.</p><h3>3. Separate global productivity from local administration</h3><p>Your design tool and your invoicing tool solve different problems. Look at local providers such as <a href="https://www.icount.co.il/" target="_blank" rel="noopener noreferrer"><u>iCount</u></a>, <a href="https://www.ezcount.co.il/" target="_blank" rel="noopener noreferrer"><u>EasyCount</u></a>, and <a href="https://www.greeninvoice.co.il/" target="_blank" rel="noopener noreferrer"><u>Morning</u></a>, and verify current suitability for your business type. These are direct links, not partnerships.</p><h3>4. Try a normal working week</h3><p>Test timezone settings, booking calendars, weekend availability, support hours, and mobile use. Ask who can recover the account if the person who created it is unavailable.</p>`},automation:{title:'Automate the boring bit first',body:`<p>The best first automation is usually a frequent, low-risk handoff that everyone already understands.</p><h3>Map one tiny workflow</h3><p>For example: a client completes an intake form, a task is created, and the team gets a notification. Write down the trigger, required fields, destination, and person responsible when something fails.</p><h3>Check the failure path</h3><p>What happens when a field is missing, the same request arrives twice, or an app is offline? Start with test data and keep a manual fallback.</p><h3>Compare cost at realistic volume</h3><p>Make, Zapier, and n8n use different product and billing structures. Check official terms, connector availability, hosting costs, and expected usage instead of choosing only from the headline plan.</p><h3>Keep the human decision</h3><p>Automate copying information before automating approvals, purchases, or customer promises. Give the workflow a named owner and revisit it after the first week.</p>`}};
function guide(key){const g=guides[key];modal(`<div class="eyebrow">FIELD NOTES / ENGLISH EDITION</div><h2 lang="en" dir="ltr">${g.title}</h2><div lang="en" dir="ltr">${g.body}</div><p class="source-note">Warez editorial guidance · 16 October 2026 · General decision support, not a vendor review.</p>`)}
function legal(key){const text={about:`<h2>Less noise. More useful.</h2><p>Warez.co.il is an independent, launch-stage software discovery project for freelancers and small businesses, with local context for Israeli teams.</p><h3>How the shortlist works</h3><p>Tools are selected for a clear small-business use case, an official product destination, and a range of cost and ownership models. Descriptions summarize first-party product pages accessed on 16 October 2026. Inclusion is editorial judgment, not a hands-on review, security audit, certification, numerical ranking, or guarantee.</p><p>Editorial order groups approachable starting points first. Search and filters operate on this curated dataset. The collection is deliberately small and does not represent the entire market.</p><h3>The business model</h3><p>Potential revenue comes from disclosed affiliate referrals and clearly labeled sponsorships. The desk essentials section and its buying guide use Amazon affiliate links. As an Amazon Associate I earn from qualifying purchases. No paid sponsor listings are currently configured. Payment never buys a review score.</p>`,disclosure:`<h2>Commercial disclosure</h2><p>The desk essentials section and buying guide contain Amazon affiliate links. As an Amazon Associate I earn from qualifying purchases. Warez may receive a commission when visitors make qualifying purchases through these links. These links are disclosed alongside the recommendations and marked as sponsored in their metadata.</p><p>The software directory continues to link directly to official vendors; the Amazon affiliate links are in the desk essentials recommendations. Proposed sponsor packages do not represent existing advertisers, sales, traffic, or guaranteed returns.</p><p>Sponsored placements must be explicitly labeled. Editorial inclusion and descriptions stay independent. Product names belong to their respective owners; listing a product does not imply affiliation.</p>`,privacy:`<h2>Your privacy at Warez.</h2><p>Warez uses first-party analytics to understand page visits, referral websites and campaign tags, approximate country and city, device and browser categories, time spent, site search terms, and outbound link destinations. Do not enter personal information into site search.</p><p>No advertising pixels or cross-site tracking cookies are used. A temporary identifier in this tab links page visits. Visitor estimates use a daily changing identifier derived from connection details; raw IP addresses and full browser strings are not stored in our analytics database. Estimates are approximate, and locations may reflect VPNs or networks. Event records are retained for up to 90 days. Aggregated Google search performance may be imported separately from Search Console.</p><p>The tracker respects Do Not Track, Global Privacy Control, and your choice below. Opting out stops future collection in this browser; it does not erase previously anonymized statistics.</p><button class="outline" id="analytics-choice">Toggle analytics opt-out</button><p>Your shortlist and language preference are stored locally. You can erase those preferences below. Hosting providers process connection information under their own policies. Google Fonts supplies typography. Vendor and Amazon links lead to third-party sites with their own policies. Amazon affiliate links include a tracking tag so Amazon can attribute qualifying referrals; Amazon may use cookies or other tracking under its own privacy policy after you follow a link.</p><button class="outline" id="erase-data">Erase my local Warez preferences</button>`};modal(text[key])}
function download(name,text){const blob=new Blob([text],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function sponsor(){modal(`<h2>${tr('A useful partnership.','שותפות שימושית.')}</h2><p class="modal-intro">${tr('Build a clear brief for an introductory sponsor conversation.','בונים מסמך ברור לשיחת חסות ראשונית.')}</p><div class="notice">${tr(`Proposed launch package: ₪${config.sponsorRateILS} for a 30-day, clearly labeled placement. This is a planning offer, not a checkout. No audience size, leads, clicks, or sales are guaranteed.`,`הצעת השקה: ₪${config.sponsorRateILS} ל־30 יום במיקום מסומן כחסות. זו הצעה לתכנון, לא עמוד תשלום. אין הבטחה לקהל, לידים, קליקים או מכירות.`)}</div><p>${config.contactEmail||config.sponsorFormUrl?tr('Prepare your brief below, then use the configured contact option.','מכינים את המסמך ומשתמשים באפשרות יצירת הקשר.'):tr('Sponsor booking is not open yet. You can download a brief now; no information will be sent or stored by Warez.','הזמנת חסויות עדיין אינה פתוחה. אפשר להוריד מסמך כעת; המידע אינו נשלח או נשמר ב־Warez.')}</p><form id="sponsor-form" class="sponsor-form"><label>${tr('Product or company','מוצר או חברה')}<input name="company" required maxlength="120" autocomplete="organization"></label><label>${tr('Your website (https://)','אתר החברה (https://)')}<input name="website" type="url" required placeholder="https://" pattern="https://.*"></label><label>${tr('Audience fit / what you make','התאמה לקהל / מה אתם בונים')}<textarea name="message" required maxlength="2000"></textarea></label><button class="dark" type="submit">${tr('Download my brief ↓','הורדת המסמך שלי ↓')}</button></form>${validUrl(config.sponsorFormUrl)?`<div class="modal-actions"><a class="outline" href="${esc(config.sponsorFormUrl)}" target="_blank" rel="noopener noreferrer">Open sponsor inquiry form ↗</a></div>`:''}${/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(config.contactEmail)?`<p><a href="mailto:${esc(config.contactEmail)}"><u>Email the owner ↗</u></a></p>`:''}<p class="source-note">Launch-stage proposal. Availability, suitability, disclosures, payment terms, and refunds must be agreed with the owner before any sale. No money is collected on this page.</p>`)}
document.addEventListener('click',event=>{const el=event.target.closest('button');if(!el)return;if(el.dataset.category){category=el.dataset.category;expanded=false;render()}if(el.dataset.search){$('#search').value=el.dataset.search==='free'?'':el.dataset.search;$('#free-only').checked=el.dataset.search==='free';expanded=true;savedOnly=false;render();$('#discover').scrollIntoView()}if(el.hasAttribute('data-reset'))reset();if(el.dataset.save){const id=el.dataset.save;saved.has(id)?saved.delete(id):saved.add(id);write('warez-saved',[...saved]);render();if($('#dialog').open)toolDetail(id);toast(tr('Shortlist updated','הרשימה עודכנה'))}if(el.dataset.detail)toolDetail(el.dataset.detail);if(el.dataset.stack)stackDetail(el.dataset.stack);if(el.dataset.guide)guide(el.dataset.guide);if(el.dataset.legal)legal(el.dataset.legal);if(el.dataset.saveStack){stacks[el.dataset.saveStack].ids.forEach(id=>saved.add(id));write('warez-saved',[...saved]);render();toast(tr('Stack saved to your shortlist','הערכה נשמרה ברשימה'))}if(el.dataset.compareStack){compare=new Set(stacks[el.dataset.compareStack].ids);render();comparison()}if(el.id==='analytics-choice'){try{const off=localStorage.getItem('warez-analytics-optout')!=='1';localStorage.setItem('warez-analytics-optout',off?'1':'0');toast(off?'Analytics is now disabled in this browser':'Analytics will resume on your next page visit')}catch{toast('Your browser blocked preference storage')}}if(el.id==='erase-data'){saved.clear();lang='en';try{localStorage.removeItem('warez-saved');localStorage.removeItem('warez-language')}catch{}$('#dialog').close();setLanguage();toast('Local Warez data erased')}});
document.addEventListener('change',event=>{if(event.target.dataset.compare){const id=event.target.dataset.compare;if(compare.has(id))compare.delete(id);else if(compare.size<3)compare.add(id);else toast(tr('Choose up to three tools. Remove one first.','אפשר לבחור עד שלושה כלים. הסירו אחד תחילה.'));render()}});
$('#search').addEventListener('input',()=>{expanded=true;render()});$('#search-form').addEventListener('submit',e=>{e.preventDefault();expanded=true;render();$('#discover').scrollIntoView()});$('#free-only').addEventListener('change',render);$('#sort').addEventListener('change',render);$('#clear').addEventListener('click',reset);$('#show-all').addEventListener('click',()=>{expanded=true;render()});$('#saved').addEventListener('click',()=>{reset();savedOnly=true;expanded=true;render();$('#discover').scrollIntoView()});$('#language').addEventListener('click',()=>{lang=lang==='en'?'he':'en';write('warez-language',lang);setLanguage()});$('#compare-open').addEventListener('click',comparison);$('#compare-clear').addEventListener('click',()=>{compare.clear();render()});$('#dialog-close').addEventListener('click',()=>$('#dialog').close());$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const b=$('#dialog').getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)$('#dialog').close()}});$('#sponsor').addEventListener('click',sponsor);
document.addEventListener('submit',e=>{if(e.target.id!=='sponsor-form')return;e.preventDefault();const f=new FormData(e.target);download('warez-partnership-brief.txt',`WAREZ.CO.IL — SPONSORSHIP INQUIRY BRIEF\nPrepared: ${new Date().toISOString().slice(0,10)}\n\nCompany: ${f.get('company')}\nWebsite: ${f.get('website')}\nAudience fit: ${f.get('message')}\n\nProposed launch package: ILS ${config.sponsorRateILS} / 30 days. Clearly labeled placement, subject to owner approval and written terms. No traffic or conversion guarantee.\n\nNo payment or inquiry was transmitted. Share this brief only with a verified owner contact once booking opens.\n`);toast(tr('Brief downloaded. Nothing was sent.','המסמך הורד. דבר לא נשלח.'))});
const params=new URLSearchParams(location.search);if(params.get('q')){$('#search').value=params.get('q');expanded=true}if(params.get('category')&&categories.some(x=>x[0]===params.get('category'))){category=params.get('category');expanded=true}setLanguage();
})();
